"use client";
import { useEffect, useRef, useState, type ComponentProps } from "react";
import { cn } from "./lib/cn";
import "./clip-reveal.css";

export type ClipRevealProps = ComponentProps<"div"> & {
  /** The edge the wipe starts from, or an iris that opens from the middle. */
  from?: "bottom" | "top" | "left" | "right" | "iris";
  /** Hides again when scrolled out of view, so the wipe plays each time. */
  repeat?: boolean;
  /** Extra wait before the wipe, in ms, for staggering neighbours. */
  delay?: number;
};

/**
 * Uncovers an image or section with a wipe as it scrolls into view, the content settling from a slight zoom behind
 * the edge. It never changes layout. Anything already on screen when the page loads is left as it is, so nothing
 * flashes away and back, and under reduced motion everything simply shows.
 */
export function ClipReveal({ from = "bottom", repeat = false, delay = 0, className, style, children, ...props }: ClipRevealProps) {
  const root = useRef<HTMLDivElement>(null);
  const [state, setState] = useState<"idle" | "hidden" | "shown">("idle");

  useEffect(() => {
    const element = root.current;
    if (!element || matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    let armed = false;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (!entry) return;
        if (!armed) {
          armed = true;
          // Only arm what starts out of view; content already visible stays put.
          if (entry.isIntersecting) {
            if (!repeat) observer.disconnect();
            return;
          }
          setState("hidden");
          return;
        }
        if (entry.isIntersecting) {
          setState("shown");
          if (!repeat) observer.disconnect();
        } else if (repeat) setState("hidden");
      },
      { threshold: 0.2 },
    );
    observer.observe(element);
    return () => observer.disconnect();
  }, [repeat]);

  return (
    <div
      ref={root}
      data-slot="clip-reveal"
      data-from={from}
      data-state={state}
      className={cn("relative overflow-hidden", className)}
      style={style}
      {...props}
    >
      <div data-slot="cr-inner" style={{ transitionDelay: `${delay}ms` }}>
        {children}
      </div>
    </div>
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/* clip-reveal.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Clip reveal: only parts armed below the fold start hidden; the content settles from a slight zoom behind the edge. */
  /* The wipe is on the inner layer: a box clipped to nothing never reports itself in view, so the observed root stays whole. */
  [data-slot="clip-reveal"] > [data-slot="cr-inner"] { height: 100%; clip-path: inset(0); transition: clip-path 0.95s var(--ease-showcase), scale 1.2s var(--ease-showcase); }
  [data-slot="clip-reveal"][data-state="hidden"] > [data-slot="cr-inner"] { scale: 1.08; transition: none; }
  [data-slot="clip-reveal"][data-state="hidden"][data-from="bottom"] > [data-slot="cr-inner"] { clip-path: inset(100% 0 0 0); }
  [data-slot="clip-reveal"][data-state="hidden"][data-from="top"] > [data-slot="cr-inner"] { clip-path: inset(0 0 100% 0); }
  [data-slot="clip-reveal"][data-state="hidden"][data-from="left"] > [data-slot="cr-inner"] { clip-path: inset(0 100% 0 0); }
  [data-slot="clip-reveal"][data-state="hidden"][data-from="right"] > [data-slot="cr-inner"] { clip-path: inset(0 0 0 100%); }
  [data-slot="clip-reveal"][data-state="hidden"][data-from="iris"] > [data-slot="cr-inner"] { clip-path: inset(50% 50% 50% 50% round 999px); }
  [data-slot="clip-reveal"][data-from="iris"][data-state="shown"] > [data-slot="cr-inner"] { clip-path: inset(0 0 0 0 round 0); }
  @media (prefers-reduced-motion: reduce) {
    [data-slot="clip-reveal"], [data-slot="clip-reveal"] > [data-slot="cr-inner"] { transition: none; }
  }
}
